```cpp
#include <iostream>
#include <unordered_map>

class LRUCache {
private:
    // 双向链表节点
    struct Node {
        int key;
        int value;
        Node* prev;
        Node* next;

        Node(int k, int v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    // 双向链表类
    class DoublyLinkedList {
    public:
        Node* head;
        Node* tail;

        DoublyLinkedList() {
            head = new Node(-1, -1);  // 虚拟头节点
            tail = new Node(-1, -1);  // 虚拟尾节点
            head->next = tail;
            tail->prev = head;
        }

        ~DoublyLinkedList() {
            delete head;
            delete tail;
        }

        // 在头部插入节点
        void addToHead(Node* node) {
            node->prev = head;
            node->next = head->next;
            head->next->prev = node;
            head->next = node;
        }

        // 删除指定节点
        void removeNode(Node* node) {
            node->prev->next = node->next;
            node->next->prev = node->prev;
        }

        // 移动节点到头部
        void moveToHead(Node* node) {
            removeNode(node);
            addToHead(node);
        }

        // 删除尾部节点（返回被删除的节点）
        Node* removeTail() {
            Node* lastNode = tail->prev;
            removeNode(lastNode);
            return lastNode;
        }
    };

    int capacity_;
    int size_;
    std::unordered_map<int, Node*> cache;  // 哈希表：key -> Node*
    DoublyLinkedList dll;

public:
    LRUCache(int capacity) : capacity_(capacity), size_(0) {}

    int get(int key) {
        if (cache.find(key) == cache.end()) {
            return -1;  // 键不存在
        }

        // 找到节点，移动到头部（标记为最近使用）
        Node* node = cache[key];
        dll.moveToHead(node);

        return node->value;
    }

    void put(int key, int value) {
        if (cache.find(key) == cache.end()) {
            // 键不存在，需要插入新节点
            Node* newNode = new Node(key, value);

            if (size_ >= capacity_) {
                // 容量已满，删除最久未使用的节点（尾部前一个节点）
                Node* tailNode = dll.removeTail();
                cache.erase(tailNode->key);
                delete tailNode;
                size_--;
            }

            // 插入新节点到头部
            dll.addToHead(newNode);
            cache[key] = newNode;
            size_++;
        } else {
            // 键存在，更新值并移动到头部
            Node* node = cache[key];
            node->value = value;
            dll.moveToHead(node);
        }
    }

    // 析构函数清理内存
    ~LRUCache() {
        for (auto& pair : cache) {
            delete pair.second;
        }
    }
};

