    lru.put(3, 3);  // 该操作会使得键 2 作废
    std::cout << "put(3, 3) - 驱逐了键 2\n";

    std::cout << "get(2): " << lru.get(2) << "\n";  // 返回 -1 (未找到)

    lru.put(4, 4);  // 该操作会使得键 1 作废
    std::cout << "put(4, 4) - 驱逐了键 1\n";

    std::cout << "get(1): " << lru.get(1) << "\n";  // 返回 -1 (未找到)
